      thresholdText,
      priceRowsHtml,
      detectedPriceModelsHtml,
      settingsProviderNames,
      cloneSettingsPriceTable,
      suggestedProviderEnvironmentKey,
      ensureCodexProviderDraft,
      providerDraftFromSettings,
      ensureSettingsProviderDraft,
      openCodexCliDialog,
      closeCodexCliDialog,
